\label{def:gf2}
The field $\mathbb{F}_2$ has elements $0$ and $1$, with addition and
multiplication modulo two. In particular, $1+1=0$.
\end{definition}","content_sha256":"e7bd86d157279d463b0ae1d01d63420e9e7d58a8a7d41574aa5de19b296c0a06","data":{"environment":"definition","order":2,"author_claims_formalized":false,"identity_basis":"label","semantic_context_sha256":"66f00aa7044b5592ababa9b442147fd36d94cb2df26fe437dc876371937d734f"},"review_status":"extracted","verification_status":"not_verified","revision":"489c1af05106575a0cd9d2e29adfe84cebc42d2001753339639491676c6206f2","record_path":"nodes/definition/qec-demo-label-def-gf2--a9e41a8adf808739.json","fragment_path":"nodes/definition/qec-demo-label-def-gf2--a9e41a8adf808739.tex"},{"id":"qec-demo:label:proof:hgp-css","kind":"proof","origin":"parser","title":"proof:hgp-css","labels":["proof:hgp-css"],"source":{"path":"sections/hgp.tex","char_start":669,"char_end":1064,"line_start":22,"line_end":33,"file_sha256":"d095f5da29c1d7bf41ba9023f0b8fbced21ab5937b4fd11fbc746db297a45866","coordinate_system":"unicode_codepoints_half_open; lines_1based_inclusive"},"latex":"\begin{proof}
\label{proof:hgp-css}
\uses{def:gf2,lem:css-commutation}
Multiplying the two blocks gives
\begin{equation}
\label{eq:hgp-commutation}
H_XH_Z^T=H_1\otimes H_2^T+H_1\otimes H_2^T=0.
\end{equation}
The last equality uses the field in Definition~\ref{def:gf2}.
Lemma~\ref{lem:css-commutation} identifies this binary identity with
pairwise commutation of the CSS generators.
\end{proof}","content_sha256":"98529426bf3b4d1f4168925381ed84ccaebefd12f4ddf6bd6762f72e9b32d203","data":{"environment":"proof","order":13,"author_claims_formalized":false,"identity_basis":"label","semantic_context_sha256":"66f00aa7044b5592ababa9b442147fd36d94cb2df26fe437dc876371937d734f"},"review_status":"extracted","verification_status":"not_verified","revision":"6022caefa15323be747f2e001a0e71e5d744858ff6737ab0055181a8f9b505eb","record_path":"nodes/proof/qec-demo-label-proof-hgp-css--016f63d14c20f569.json","fragment_path":"nodes/proof/qec-demo-label-proof-hgp-css--016f63d14c20f569.tex"},{"id":"qec-demo:label:lem:css-commutation","kind":"lemma","origin":"parser","title":"Pairwise commutation","labels":["lem:css-commutation"],"source":{"path":"sections/foundations.tex","char_start":803,"char_end":1111,"line_start":27,"line_end":35,"file_sha256":"f7329e1c1e3ff8a8a13a8cbb4907545cd12c9ab9ac5629728a9ff8d884610b3e","coordinate_system":"unicode_codepoints_half_open; lines_1based_inclusive"},"latex":"\begin{lem}[Pairwise commutation]
\label{lem:css-commutation}
\uses{def:css,def:gf2}
\lean{QEC.Examples.binary_css_commutation}
\leanok
