\label{thm:hgp-length}
Use the construction of Theorem~\ref{thm:hgp-css} with
\begin{equation}
\label{eq:repetition-seed}
H_1=H_2=
\begin{pmatrix}
1&1&0\\
0&1&1
\end{pmatrix}.
\end{equation}
The resulting presentation has thirteen data qubits.
\end{thm}","content_sha256":"f14d0cff2b278fed3b7c2e6321696d027a1a59a2bda02a85cbe0d5b3fe48654d","data":{"environment":"thm","order":15,"author_claims_formalized":false,"identity_basis":"label","semantic_context_sha256":"66f00aa7044b5592ababa9b442147fd36d94cb2df26fe437dc876371937d734f"},"review_status":"extracted","verification_status":"not_verified","revision":"ba53a6aaca23d86f5ac7aa775bbd8d044d35c3491209df8530c8c9b69321c08c","record_path":"nodes/theorem/qec-demo-label-thm-hgp-length--a09c951c27a7543e.json","fragment_path":"nodes/theorem/qec-demo-label-thm-hgp-length--a09c951c27a7543e.tex"},{"id":"qec-demo:label:eq:css-commutation","kind":"equation","origin":"parser","title":"eq:css-commutation","labels":["eq:css-commutation"],"source":{"path":"sections/foundations.tex","char_start":564,"char_end":637,"line_start":18,"line_end":21,"file_sha256":"f7329e1c1e3ff8a8a13a8cbb4907545cd12c9ab9ac5629728a9ff8d884610b3e","coordinate_system":"unicode_codepoints_half_open; lines_1based_inclusive"},"latex":"\begin{equation}
