\label{proof:hgp-length}
\proves{thm:hgp-length}
\uses{thm:hgp-css}
Each seed in Equation~\eqref{eq:repetition-seed} has $n_i=3$ columns
and $m_i=2$ rows. The first block in
Equation~\eqref{eq:hgp-checks} has $n_1n_2=9$ columns, and the second
has $m_1m_2=4$ columns. Hence $n=9+4=13$.
\end{proof}","content_sha256":"e3f29e07c2a9b068ed975829780d14f85944772691fb7c68db7cbdfa3e9380f0","data":{"environment":"proof","order":20,"author_claims_formalized":false,"identity_basis":"label","semantic_context_sha256":"66f00aa7044b5592ababa9b442147fd36d94cb2df26fe437dc876371937d734f"},"review_status":"extracted","verification_status":"not_verified","revision":"777e9748ba0bb16409eab22334dab17a7eb29b9c7be99e84488e576b760d8228","record_path":"nodes/proof/qec-demo-label-proof-hgp-length--91bd0f82ece89fec.json","fragment_path":"nodes/proof/qec-demo-label-proof-hgp-length--91bd0f82ece89fec.tex"},{"id":"lean:qec-demo:QEC.Examples.binary_css_commutation","kind":"lean_declaration","title":"QEC.Examples.binary_css_commutation","origin":"parser","data":{"declaration":"QEC.Examples.binary_css_commutation","project_revision":null,"build_evidence":null,"mapping_status":"author_declared","proof_status":"not_checked"},"review_status":"extracted","verification_status":"not_verified","labels":[],"latex":"","source":null,"content_sha256":"18d792955bdeff8e671791fa1759c3e0b316057977d3996ad41f2f921c082996","revision":"aa131eb66447873856c8564dcf8c18eebbfdc131871275e83caa885ba61be078","record_path":"nodes/lean_declaration/lean-qec-demo-QEC-Examples-binary_css_commutation--8762751942f4921b.json"},{"id":"qec-demo:label:sec:hgp","kind":"section","origin":"parser","title":"An ordinary hypergraph product","labels":["sec:hgp"],"source":{"path":"sections/hgp.tex","char_start":0,"char_end":56,"line_start":1,"line_end":2,"file_sha256":"d095f5da29c1d7bf41ba9023f0b8fbced21ab5937b4fd11fbc746db297a45866","coordinate_system":"unicode_codepoints_half_open; lines_1based_inclusive"},"latex":"\section{An ordinary hypergraph product}
