\label{proof:css-commutation}
\uses{def:css}
For binary row vectors $x,z$, the Pauli relation gives
\begin{equation*}
X(x)Z(z)=(-1)^{x\cdot z}Z(z)X(x).
\end{equation*}
Thus the pair commutes exactly when its dot product is zero in
$\mathbb{F}_2$. Applying this statement to every pair of generator rows
gives Equation~\eqref{eq:css-commutation}.
\end{proof}","content_sha256":"545f6cf4c358215a5f1845ea35f8ca2201dc532a7413f8b54e4a3f6516e1171a","data":{"environment":"proof","order":6,"author_claims_formalized":false,"identity_basis":"label","semantic_context_sha256":"66f00aa7044b5592ababa9b442147fd36d94cb2df26fe437dc876371937d734f"},"review_status":"extracted","verification_status":"not_verified","revision":"0ddd65b481f2899611c5a4fa220e0f36a1da943dd3aa71523a70d888714628c1","record_path":"nodes/proof/qec-demo-label-proof-css-commutation--a4abcad175473b48.json","fragment_path":"nodes/proof/qec-demo-label-proof-css-commutation--a4abcad175473b48.tex"},{"id":"qec-demo:label:proof:hgp-css","kind":"proof","origin":"parser","title":"proof:hgp-css","labels":["proof:hgp-css"],"source":{"path":"sections/hgp.tex","char_start":669,"char_end":1064,"line_start":22,"line_end":33,"file_sha256":"d095f5da29c1d7bf41ba9023f0b8fbced21ab5937b4fd11fbc746db297a45866","coordinate_system":"unicode_codepoints_half_open; lines_1based_inclusive"},"latex":"\begin{proof}
\label{proof:hgp-css}
\uses{def:gf2,lem:css-commutation}
Multiplying the two blocks gives
\begin{equation}
\label{eq:hgp-commutation}
H_XH_Z^T=H_1\otimes H_2^T+H_1\otimes H_2^T=0.
\end{equation}
The last equality uses the field in Definition~\ref{def:gf2}.
Lemma~\ref{lem:css-commutation} identifies this binary identity with
pairwise commutation of the CSS generators.
\end{proof}","content_sha256":"98529426bf3b4d1f4168925381ed84ccaebefd12f4ddf6bd6762f72e9b32d203","data":{"environment":"proof","order":13,"author_claims_formalized":false,"identity_basis":"label","semantic_context_sha256":"66f00aa7044b5592ababa9b442147fd36d94cb2df26fe437dc876371937d734f"},"review_status":"extracted","verification_status":"not_verified","revision":"6022caefa15323be747f2e001a0e71e5d744858ff6737ab0055181a8f9b505eb","record_path":"nodes/proof/qec-demo-label-proof-hgp-css--016f63d14c20f569.json","fragment_path":"nodes/proof/qec-demo-label-proof-hgp-css--016f63d14c20f569.tex"},{"id":"lean:qec-demo:QEC.Examples.binary_css_commutation","kind":"lean_declaration","title":"QEC.Examples.binary_css_commutation","origin":"parser","data":{"declaration":"QEC.Examples.binary_css_commutation","project_revision":null,"build_evidence":null,"mapping_status":"author_declared","proof_status":"not_checked"},"review_status":"extracted","verification_status":"not_verified","labels":[],"latex":"","source":null,"content_sha256":"18d792955bdeff8e671791fa1759c3e0b316057977d3996ad41f2f921c082996","revision":"aa131eb66447873856c8564dcf8c18eebbfdc131871275e83caa885ba61be078","record_path":"nodes/lean_declaration/lean-qec-demo-QEC-Examples-binary_css_commutation--8762751942f4921b.json"},{"id":"qec-demo:paragraph:anon:24d8674777689c9e","kind":"paragraph","origin":"parser","title":"paragraph","labels":[],"source":{"path":"sections/hgp.tex","char_start":1373,"char_end":1567,"line_start":49,"line_end":52,"file_sha256":"d095f5da29c1d7bf41ba9023f0b8fbced21ab5937b4fd11fbc746db297a45866","coordinate_system":"unicode_codepoints_half_open; lines_1based_inclusive"},"latex":"For background and motivation, compare Theorem~\ref{thm:hgp-css}.
