\label{thm:hgp-length}
Use the construction of Theorem~\ref{thm:hgp-css} with
\begin{equation}
\label{eq:repetition-seed}
H_1=H_2=
\begin{pmatrix}
1&1&0\\
0&1&1
\end{pmatrix}.
\end{equation}
The resulting presentation has thirteen data qubits.
\end{thm}","content_sha256":"f14d0cff2b278fed3b7c2e6321696d027a1a59a2bda02a85cbe0d5b3fe48654d","data":{"environment":"thm","order":15,"author_claims_formalized":false,"identity_basis":"label","semantic_context_sha256":"66f00aa7044b5592ababa9b442147fd36d94cb2df26fe437dc876371937d734f"},"review_status":"extracted","verification_status":"not_verified","revision":"ba53a6aaca23d86f5ac7aa775bbd8d044d35c3491209df8530c8c9b69321c08c","record_path":"nodes/theorem/qec-demo-label-thm-hgp-length--a09c951c27a7543e.json","fragment_path":"nodes/theorem/qec-demo-label-thm-hgp-length--a09c951c27a7543e.tex"},{"id":"code:qec-demo:reported-rep3","kind":"code_instance","title":"论文示例表中描述的普通 HGP 码","origin":"sidecar","data":{"construction":"ordinary_hgp","parameters":{"n":13,"k":1},"distance":{"reported_value":3,"metric":"CSS code distance","evidence_kind":"source_reported"},"note":"These are explicitly entered sidecar fields. The LaTeX graph tool has not recomputed the parameters."},"review_status":"declared","verification_status":"not_rechecked","labels":[],"latex":"","source":null,"content_sha256":"7e023138f64eb9557b08d085a69b7fde3ab652b5f17715a98d81dbe97769a7ec","revision":"a5dbb01d60dd1e6ce0657023a76e123b20915b7a27c7087f49c89eb97bbfe080","record_path":"nodes/code_instance/code-qec-demo-reported-rep3--f5701aa1f66ece11.json"},{"id":"qec-demo:label:proof:hgp-length","kind":"proof","origin":"parser","title":"Proof of Theorem~\ref{thm:hgp-length}","labels":["proof:hgp-length"],"source":{"path":"sections/hgp.tex","char_start":2191,"char_end":2541,"line_start":73,"line_end":81,"file_sha256":"d095f5da29c1d7bf41ba9023f0b8fbced21ab5937b4fd11fbc746db297a45866","coordinate_system":"unicode_codepoints_half_open; lines_1based_inclusive"},"latex":"\begin{proof}[Proof of Theorem~\ref{thm:hgp-length}]
\label{proof:hgp-length}
\proves{thm:hgp-length}
\uses{thm:hgp-css}
Each seed in Equation~\eqref{eq:repetition-seed} has $n_i=3$ columns
and $m_i=2$ rows. The first block in
Equation~\eqref{eq:hgp-checks} has $n_1n_2=9$ columns, and the second
has $m_1m_2=4$ columns. Hence $n=9+4=13$.
\end{proof}","content_sha256":"e3f29e07c2a9b068ed975829780d14f85944772691fb7c68db7cbdfa3e9380f0","data":{"environment":"proof","order":20,"author_claims_formalized":false,"identity_basis":"label","semantic_context_sha256":"66f00aa7044b5592ababa9b442147fd36d94cb2df26fe437dc876371937d734f"},"review_status":"extracted","verification_status":"not_verified","revision":"777e9748ba0bb16409eab22334dab17a7eb29b9c7be99e84488e576b760d8228","record_path":"nodes/proof/qec-demo-label-proof-hgp-length--91bd0f82ece89fec.json","fragment_path":"nodes/proof/qec-demo-label-proof-hgp-length--91bd0f82ece89fec.tex"},{"id":"qec-demo:label:sec:foundations","kind":"section","origin":"parser","title":"Binary CSS conventions","labels":["sec:foundations"],"source":{"path":"sections/foundations.tex","char_start":0,"char_end":99,"line_start":1,"line_end":4,"file_sha256":"f7329e1c1e3ff8a8a13a8cbb4907545cd12c9ab9ac5629728a9ff8d884610b3e","coordinate_system":"unicode_codepoints_half_open; lines_1based_inclusive"},"latex":"\section{Binary CSS conventions}
