\begin{thm}[Commutation of the block construction]
\label{thm:hgp-css}
\uses{def:css}
Let $H_1\in\mathbb{F}_2^{m_1\times n_1}$ and
$H_2\in\mathbb{F}_2^{m_2\times n_2}$. Define
\begin{align}
\label{eq:hgp-checks}
H_X&=[H_1\otimes I_{n_2}\mid I_{m_1}\otimes H_2^T],\\
H_Z&=[I_{n_1}\otimes H_2\mid H_1^T\otimes I_{m_2}].
\end{align}
Then $H_XH_Z^T=0$ over $\mathbb{F}_2$.
\end{thm}

\begin{definition}[Binary CSS presentation]
\label{def:css}
\uses{def:gf2}
Let $H_X\in\mathbb{F}_2^{m_X\times n}$ and
$H_Z\in\mathbb{F}_2^{m_Z\times n}$. Rows of $H_X$ specify X-type
stabilizers, and rows of $H_Z$ specify Z-type stabilizers. The binary
commutation condition is
\begin{equation}
\label{eq:css-commutation}
H_X H_Z^{T}=0.
\end{equation}
The columns are labelled data qubits. The field is the one in
Definition~\ref{def:gf2}; the selected generator rows are part of this
presentation.
\end{definition}

\begin{definition}[Binary field]
\label{def:gf2}
The field $\mathbb{F}_2$ has elements $0$ and $1$, with addition and
multiplication modulo two. In particular, $1+1=0$.
\end{definition}

\begin{equation}
\label{eq:css-commutation}
H_X H_Z^{T}=0.
\end{equation}

\begin{lem}[Pairwise commutation]
\label{lem:css-commutation}
\uses{def:css,def:gf2}
\lean{QEC.Examples.binary_css_commutation}
\leanok
For the convention in Definition~\ref{def:css}, all X-type generators
commute with all Z-type generators if and only if
Equation~\eqref{eq:css-commutation} holds.
\end{lem}

\begin{proof}
\label{proof:css-commutation}
\uses{def:css}
For binary row vectors $x,z$, the Pauli relation gives
\begin{equation*}
X(x)Z(z)=(-1)^{x\cdot z}Z(z)X(x).
\end{equation*}
Thus the pair commutes exactly when its dot product is zero in
$\mathbb{F}_2$. Applying this statement to every pair of generator rows
gives Equation~\eqref{eq:css-commutation}.
\end{proof}

\begin{proof}
\label{proof:hgp-css}
\uses{def:gf2,lem:css-commutation}
Multiplying the two blocks gives
\begin{equation}
\label{eq:hgp-commutation}
H_XH_Z^T=H_1\otimes H_2^T+H_1\otimes H_2^T=0.
\end{equation}
The last equality uses the field in Definition~\ref{def:gf2}.
Lemma~\ref{lem:css-commutation} identifies this binary identity with
pairwise commutation of the CSS generators.
\end{proof}

\begin{thm}[Length of the repetition-seed instance]
\label{thm:hgp-length}
Use the construction of Theorem~\ref{thm:hgp-css} with
\begin{equation}
\label{eq:repetition-seed}
H_1=H_2=
\begin{pmatrix}
1&1&0\\
0&1&1
\end{pmatrix}.
\end{equation}
The resulting presentation has thirteen data qubits.
\end{thm}

\begin{proof}[Proof of Theorem~\ref{thm:hgp-length}]
\label{proof:hgp-length}
\proves{thm:hgp-length}
\uses{thm:hgp-css}
Each seed in Equation~\eqref{eq:repetition-seed} has $n_i=3$ columns
and $m_i=2$ rows. The first block in
Equation~\eqref{eq:hgp-checks} has $n_1n_2=9$ columns, and the second
has $m_1m_2=4$ columns. Hence $n=9+4=13$.
\end{proof}

\section{Binary CSS conventions}
\label{sec:foundations}

